mapper.select:
SELECT id, user_id, category, memory_text, strength, archived, embedding_json, updated_at FROM memories WHERE user_id = #{userId}
AND archived = 0
ORDER BY archived ASC, strength DESC, updated_at DESC

mapper.insert:
