  id, user_id, category, memory_text, strength, archived, embedding_json, updated_at
) VALUES (
  #{id}, #{userId}, #{category}, #{memoryText}, #{strength}, #{archived}, #{embeddingJson}, #{updatedAt}
)

mapper.select:
